const TagSelector={render:async function(selector,userOptions){const element=document.getElementById(selector);if(element.hasAttribute("tagselector")){return}element.setAttribute("tagselector","true");const options={placeholder:"Type to filter...",delimiter:",",inputClass:"",tagClass:"",tagContainerClass:"",tags:[],...userOptions};let allTags=[];let selectedTags=[];element.type="hidden";const input=document.createElement("div");input.className=`is-tag-selector-container ${options.inputClass}`;const inputSearch=document.createElement("input");inputSearch.type="text";inputSearch.placeholder=options.placeholder;inputSearch.className="is-tag-selector-input";inputSearch.addEventListener("focus",function(){input.classList.add("is-tag-selector-focused")});inputSearch.addEventListener("blur",function(){input.classList.remove("is-tag-selector-focused")});inputSearch.addEventListener("input",function(){const filter=this.value.toLowerCase();const tags=tagsContainer.querySelectorAll(".is-tag-selector-tag");tags.forEach(tag=>{tag.classList.add("is-tag-selector-filtered");if(tag.textContent.toLowerCase().includes(filter)){tag.classList.remove("is-tag-selector-filtered")}})});input.appendChild(inputSearch);const tagsContainer=document.createElement("div");tagsContainer.className=`is-tag-selector-tags ${options.tagContainerClass}`;options.tags.forEach(tag=>{const tagElement=document.createElement("a");tagElement.className=`is-tag-selector-tag ${options.tagClass}`;tagElement.textContent=tag.name;tagElement.dataset.value=tag.value;tagsContainer.appendChild(tagElement);const removeTagButton=document.createElement("span");removeTagButton.className="is-tag-selector-remove-tag";removeTagButton.textContent="✕";tagElement.appendChild(removeTagButton);allTags.push(tagElement);tagElement.addEventListener("click",function(ev){ev.preventDefault();if(selectedTags.includes(this.dataset.value)){removeTag(this.dataset.value)}else{addTag(this.dataset.value)}})});const removeTag=value=>{selectedTags=selectedTags.filter(tag=>tag!==value);const tagElement=allTags.find(t=>t.dataset.value==value);tagElement.remove();tagElement.classList.remove("is-tag-selector-selected");element.value=selectedTags.join(options.delimiter);tagsContainer.appendChild(tagElement)};const addTag=value=>{selectedTags=[...selectedTags,value];const tagElement=allTags.find(t=>t.dataset.value==value);element.value=selectedTags.join(options.delimiter);tagElement.remove();tagElement.classList.add("is-tag-selector-selected");input.prepend(tagElement)};element.parentNode.insertBefore(tagsContainer,element.nextSibling);element.parentNode.insertBefore(input,element.nextSibling);const defaultValues=element.value.split(",").filter(v=>v!="");for(let key in defaultValues){addTag(defaultValues[key])}}};